import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"AdaWorld: Learning Adaptable World Models with Latent Actions","description":"","frontmatter":{"title":"AdaWorld: Learning Adaptable World Models with Latent Actions","arxiv":"2503.18938","date":"2025-03-24","authors":"Shenyuan Gao, Siyuan Zhou, Yilun Du, Jun Zhang, Chuang Gan","categories":"cs.AI, cs.CV, cs.LG, cs.RO","topics":"世界模型, latent action, 高效适配","outline":[2,2]},"headers":[],"relativePath":"papers/2503.18938.md","filePath":"papers/2503.18938.md","lastUpdated":null}'),l={name:"papers/2503.18938.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="adaworld-learning-adaptable-world-models-with-latent-actions" tabindex="-1">AdaWorld: Learning Adaptable World Models with Latent Actions <a class="header-anchor" href="#adaworld-learning-adaptable-world-models-with-latent-actions" aria-label="Permalink to &quot;AdaWorld: Learning Adaptable World Models with Latent Actions&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.18938" target="_blank" rel="noreferrer">2503.18938</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-24</td></tr><tr><td><strong>作者</strong></td><td>Shenyuan Gao, Siyuan Zhou, Yilun Du, Jun Zhang, Chuang Gan</td></tr><tr><td><strong>分类</strong></td><td>cs.AI, cs.CV, cs.LG, cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>在世界模型<strong>预训练阶段</strong>就把自监督抽出的连续 latent action 当作统一条件，使得适配新环境退化为「把新动作空间映射到这套 latent action 上」，几十到一百条交互样本即可完成。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>世界模型的主流做法是从预训练视频模型出发（Pandora、Cosmos 这一类），再用带动作标注的数据教会它响应控制。这套流程的成本结构很别扭：视频预训练可以用海量无标注数据、几乎无限扩展，但<strong>动作可控性</strong>这一步必须要动作标注，而不同环境的动作规格完全不同——Minecraft 是键鼠、机械臂是关节位移、自动驾驶是速度与曲率。换一个环境，就要重新收集标注、重新训练一遍控制接口。</p><p>论文要解决的是：<strong>能不能让世界模型在换环境时只需要极少量交互（比如每个动作 100 条样本、800 步微调）就获得精确控制？</strong> ICML 2025 接收。这个问题的价值在于，它决定了世界模型能不能成为一种「可复用的基础设施」，而不是每个任务都要从头造一遍的一次性产物。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>动作无关的视频预训练。</strong> APV、Structured World Models、ContextWM 这一线已经在做从被动视频里预训练世界模型。作者的批评很精确：它们的目标是获得紧凑的<strong>世界表征</strong>，而不是学一个<strong>可以被少量交互快速适配的控制接口</strong>。表征好不等于控制接口好——控制接口需要模型已经理解「不同的动作会导致不同的转移」，而动作无关预训练时模型从未见过这种因果结构。</p><p><strong>参数高效的在线适配。</strong> Probabilistic Adaptation、AVID、SlowFast-VGen 这一线关注的是参数效率，前提假设是预训练视频模型的参数被冻结或不可访问。这与本文的设定不同，也回避了「预训练该学什么」这个问题。</p><p><strong>latent action 的已有工作。</strong> Genie 从 2D 游戏视频学可玩环境，但只有 8 个固定的离散动作，表达能力受限；IGOR、Moto、LAPA、VideoWorld 这一批把 latent action 扩展到多数据集，但主要把它当作 behavior cloning 的目标，为了适配策略网络几乎都用离散动作，而离散化会带来显著歧义（Nikulin et al. 2025 有专门讨论）。作者的判断是：latent action 用于<strong>可适配世界建模</strong>的潜力还没被开发。</p><p><strong>伪标注路线。</strong> VPT、SelfD 这类为视频打伪动作标签的做法，需要先定义一个统一的动作格式，而对通用环境这件事本身就不可行。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>已有的观察摆在这里。第一，人类看别人做一遍就能估计动作的效果，这种能力来自长期观察中形成的内部动作表示（论文引了 premotor cortex 与镜像神经元的文献）。第二，在大多数交互场景里，画面帧间的<strong>主要变化</strong>就是智能体的动作造成的——Rybkin et al. 2019、Playable Video Generation、Genie 都基于这个观察。第三，VAE 的信息瓶颈是一个现成的、把「主变化」从「上下文」里挤出来的工具。</p><p>把这三点连起来：如果强迫一个编码器只用极少的比特去描述相邻两帧的差异，然后要求解码器仅凭这几个比特加上前一帧就重建后一帧，那么这几个比特必然被迫编码「最关键的变化」，也就是动作。而颜色、纹理这些上下文信息因为在前一帧里已有，不值得占用瓶颈带宽。这就得到了<strong>上下文无关</strong>的动作表示。</p><p>再往前一步：如果预训练时世界模型的条件就是这种 latent action，那么它见过的是「各种各样的动作会导致各种各样的转移」。换环境时，模型不需要重新学「动作如何影响世界」，只需要找到新环境的动作空间到这套 latent action 的映射——这是一个维度极低的问题，几十条样本就够。</p><p>至于离散还是连续：Genie 用离散是为了适配策略网络的分类头，但本文的目标是世界建模而非行为克隆，没有这个约束，连续空间能保留更细腻的动作差异，还能做插值与组合。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>现有世界模型换环境要重训，是因为它们在预训练时压根没学过「动作」这个概念，控制接口是事后焊上去的。如果预训练时就用一个自监督抽出的、跨环境通用的连续动作表示作条件，模型学到的就是「给定任意动作表示如何演化世界」这件通用的事。此后适配一个新环境不再是学习新知识，而是<strong>查表</strong>——找到新动作对应的那个 latent action 就行。信息瓶颈是让这个表示跨环境通用的关键：带宽越窄，编码进去的就越是动作本身，越少是上下文。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「把在 Something-Something v2 里演示的『把物体向上移动』迁移到一个 LIBERO 机器人场景」为例：</p><ul><li><strong>latent action autoencoder（500M 参数）</strong>。编码器把相邻两帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9028em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 切成 16×16 patch 投影成 embedding，拼上两个可学习 token <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>，过 16 个时空 Transformer block（空间注意力看帧内全部 token，时间注意力只看两帧同一空间位置的 token，时间注意力里加 rotary embedding 表示因果关系）。之后丢弃所有 token，只把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 投影成后验参数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">μ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord accent mtight"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.7em;"><span class="pstrut" style="height:2.7em;"></span><span class="mord mathnormal mtight">a</span></span><span style="top:-3.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord mtight">~</span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord accent mtight"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.7em;"><span class="pstrut" style="height:2.7em;"></span><span class="mord mathnormal mtight">a</span></span><span style="top:-3.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord mtight">~</span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，采样得到 32 维的 latent action <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6679em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span></span></span></span>。解码器是一个空间 Transformer，仅凭 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6679em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在像素空间预测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9028em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>。训练 200K 步，batch 960，AdamW lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2.5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>。</li><li><strong>action-aware pretraining（1.5B 参数世界模型）</strong>。用上面的编码器从无标注视频里抽 latent action，作为条件预训练一个自回归世界模型。底座是 Stable Video Diffusion（EDM 框架），但每次只去噪<strong>一帧</strong>，从而支持帧级控制粒度。latent action 与 timestep embedding 及 CLIP image embedding 拼接后深度注入；记忆里最后一帧作为 SVD 的 condition image；历史帧用 SVD image encoder 编码后与待预测帧的噪声 latent 拼接。训练时随机采样最多 6 帧历史并把记忆长度作为条件送入，且对历史帧做噪声增强来缓解长时漂移（推理时不加噪也有效）。80K 步，batch 64，16 张 A100，分辨率 256×256。</li><li><strong>训练数据</strong>。四个公开数据集（SSv2、Ego4D、Open X-Embodiment、MiraData）加上自动生成的游戏数据：从网上导入 1000 个 ROM 到 Gym Retro 各采 100 万条转移，Procgen 的 16 个环境各采 1000 万条。总计约 20 亿帧。采样策略上没有像 Genie 那样均匀随机，而是<strong>有偏采样</strong>——短期内提高某个动作的选择概率，之后再轮换，以鼓励更长距离的探索、得到更多样的场景。混合比例：Gym Retro 49%、OpenX 30%、MiraData 3D 渲染 14%、SSv2 3%、Procgen 2%、Ego4D 与 city walking 各 1%。</li><li><strong>三种下游用法</strong>。(1) 动作迁移：从演示视频抽 latent action 序列，配上新场景的首帧自回归生成；(2) 世界模型适配：对离散动作空间，采少量交互样本，把同一标签下的 latent action <strong>直接平均</strong>作为该动作的 embedding 初始化，再整体微调几百步；对连续动作空间（如 nuScenes），加一个两层 MLP 把原始位移映射到 latent action 接口，用极少配对样本微调 3K 步（单卡 30 秒内）；(3) 动作创造：对训练集的 latent action 做 K-means，聚类中心即为可自定义数量的控制选项。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>标准 VAE 目标是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.4044em;vertical-align:-0.4374em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.967em;"><span style="top:-2.3987em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">ϕ</span></span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4374em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1333em;vertical-align:-0.3833em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-left:-0.0359em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2901em;"><span></span></span></span></span></span></span><span class="mopen mtight">(</span><span class="mord accent mtight"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.7em;"><span class="pstrut" style="height:2.7em;"></span><span class="mord mathnormal mtight">a</span></span><span style="top:-3.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord mtight">~</span></span></span></span></span></span></span><span class="mord mtight">∣</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:-0.1076em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2025em;"><span></span></span></span></span></span></span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3833em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord">∣</span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span><span class="mord mathnormal mtight">L</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mord">∣</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∥</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord">.</span></span></span></span></span></p><p>第一项要求「仅凭 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6679em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span></span></span></span> 和前一帧能重建后一帧」，第二项把后验往先验压。由于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6679em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span></span></span></span> 只有 32 维，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9028em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 是整幅图像，前一项无法靠 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6679em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span></span></span></span> 传递全部像素信息——它只能传递<strong>相对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 最关键的变化</strong>。这就是信息瓶颈把动作从上下文里挤出来的机制。</p><p>但标准 VAE 的 KL 约束太强，作者实测发现 latent action 难以表达多样的帧间转移；而完全去掉约束又会破坏解耦能力。于是改用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span>-VAE：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.4044em;vertical-align:-0.4374em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.967em;"><span style="top:-2.3987em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">ϕ</span></span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4374em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1333em;vertical-align:-0.3833em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.5198em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-left:-0.0359em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2901em;"><span></span></span></span></span></span></span><span class="mopen mtight">(</span><span class="mord accent mtight"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.7em;"><span class="pstrut" style="height:2.7em;"></span><span class="mord mathnormal mtight">a</span></span><span style="top:-3.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord mtight">~</span></span></span></span></span></span></span><span class="mord mtight">∣</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:-0.1076em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2025em;"><span></span></span></span></span></span></span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3833em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord">∣</span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span><span class="mord mathnormal mtight">L</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">ϕ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mord">∣</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∥</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord">.</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 直接控制 latent action 携带的信息量：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 越小，表达力越强但越容易混入上下文；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 越大，越纯粹是动作但表达越粗。默认 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span>。UMAP 可视化显示，在这个取值下，来自 Habitat、Minecraft、DMLab 三个不同环境的<strong>同一语义动作会聚在一起</strong>；调小 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 后类内更可分，但跨环境的重叠减少，解耦能力下降。这张图是全文对「上下文无关」这一 claim 最直接的证据。</p><p>世界模型的预训练损失是 EDM 形式的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>-prediction：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">ain</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.8em;vertical-align:-0.65em;"></span><span class="mord"><span class="mord mathbb">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord boldsymbol mtight">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">ϵ</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size2">[</span></span><span class="minner"><span class="minner"><span class="mopen delimcenter" style="top:0em;">∥</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord"><span class="mord"><span class="mord boldsymbol">x</span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">c</span></span></span><span class="mclose">)</span><span class="mclose delimcenter" style="top:0em;">∥</span></span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size2">]</span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span></span></span></span></span></p><p>条件 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol">c</span></span></span></span></span></span> 包含历史帧与 latent action <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6679em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">a</span></span><span style="top:-3.35em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">~</span></span></span></span></span></span></span></span></span></span>。</p><p>适配时的<strong>平均初始化</strong>是这套方法最省事也最关键的一步：对新环境的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 个离散动作，各采 100 条样本抽出 latent action 后直接取均值作为该动作的 embedding。这一步之所以合理，依赖于连续 latent 空间的语义连续性——同一个操作的多次执行在 latent 空间里应聚成一团，均值落在团心。论文还展示了两个 latent action 取平均能得到融合双方功能的新动作，作为语义连续性的旁证。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>对照组设置得很干净：动作无关预训练（条件恒为零）、光流条件（UniMatch 抽光流下采样到 16×16 展平）、离散 latent action（VQ-VAE，8 个码，对齐 Genie）。所有模型世界模型部分均训 50K 迭代。</p><p><strong>问题一：latent action 真的上下文无关、可迁移吗？</strong> 用未见过的 LIBERO 与 SSv2 构造 1300 对同任务/同标签视频，取第一段作演示、第二段首帧作起点，自回归生成 20 帧，用 FVD 与 ECS 评估，另做 50 对的人工判定。LIBERO 上：动作无关 1545.2 / 0.702 / 0%，光流 1409.5 / 0.724 / 2%，离散 1504.5 / 0.700 / 3.5%，AdaWorld 767.0 / 0.804 / 70.5%。SSv2 上：847.2 / 0.592 / 1%，702.8 / 0.611 / 10.5%，726.8 / 0.596 / 21.5%，AdaWorld 473.4 / 0.639 / 61.5%。人工成功率从个位数跳到 60% 以上，这个 gap 大得不像是调参能拉出来的。</p><p><strong>问题二：适配新环境的效率如何？</strong> 四个未见环境（Habitat、Minecraft、DMLab 离散，nuScenes 连续），每个动作仅 100 条样本，微调 800 步，batch 32，lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>（预训练权重的 lr 打 0.1 折扣）。PSNR/LPIPS：动作无关 20.34/0.450、19.44/0.532、20.96/0.386、20.86/0.475；AdaWorld 23.58/0.327、21.59/0.457、22.92/0.335、21.60/0.436。三个 action-aware 变体全部大幅优于动作无关基线——这一点比 AdaWorld 是否最优更重要，它直接支持了论文的核心主张：<strong>预训练时是否引入动作信息，是分水岭</strong>。</p><p><strong>问题三：适配后的模型能规划吗？</strong> Procgen 四个环境（Heist、Jumper、Maze、CaveFlyer）各 30 个场景的目标到达任务，用 CEM 优化的采样式 MPC（2 轮迭代，每轮 100 条长度 15 的动作序列，取最好 10 条更新分布，执行前 5 个动作，20 步搜索上限）。平均成功率：随机 26.17%，动作无关 26.00%（与随机无异），AdaWorld 不微调 44.83%，微调后 56.67%，Q-learning 27.17%，用真实模拟器的 Oracle 80.67%。<strong>不微调的 AdaWorld 就已经打过微调后的动作无关基线</strong>，这是对「预训练即适配」这一 claim 最有力的支持。机器人侧在 VP² 上，聚合归一化成功率从动作无关的 5.03 提到 21.54。</p><p><strong>问题四：方法是否只对自家架构有效？</strong> 把 iVideoGPT（自回归 Transformer 世界模型）改成用 latent action 做预训练条件，BAIR 上 PSNR 16.59→17.40、LPIPS 0.220→0.204。说明这是一个可移植的预训练范式而非特定架构技巧。</p><p><strong>两个值得注意的消融。</strong> 其一，接口初始化：随机初始化 AdaWorld 的控制接口，起步时略差于动作无关基线，但 200 步后就反超——说明收益主要来自预训练学到的<strong>可适配控制接口</strong>，而非那个平均初始化技巧。其二，数据多样性：只用 OpenX（真实机器人视频）训 latent action 编码器，在 Procgen 上 PSNR 25.51/LPIPS 0.318；只用 Retro 是 26.43/0.250；两者混合是 26.62/0.234。真实机器人视频竟然帮助了 2D 虚拟游戏的泛化，这一点作者自己也用了 &quot;surprisingly&quot;。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版。</strong> 现有世界模型换环境要重新收集动作标注并重训，根源是预训练阶段完全没有动作信息，控制接口是事后焊上去的。AdaWorld 用一个带信息瓶颈的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span>-VAE 从无标注视频中抽取 32 维<strong>连续</strong> latent action，因为瓶颈只放得下最关键的帧间变化，得到的表示上下文无关、跨环境可迁移。以这套 latent action 为统一条件预训练一个 1.5B 的自回归扩散世界模型（约 20 亿帧、1016 个游戏环境 + 真实机器人与人类活动视频），适配新环境退化为把新动作空间映射到 latent 空间。动作迁移的人工成功率从基线的 0 到 3.5% 跃升到 LIBERO 61.5% 到 70.5%；四个未见环境上每动作 100 样本、800 步微调即达最佳保真度。Procgen 视觉规划中<strong>未经微调</strong>的 AdaWorld（44.83%）就超过微调后的动作无关基线（26.00%）与 Q-learning（27.17%）。</p><p><strong>3 句话版。</strong> 把动作信息提前到世界模型预训练阶段，用信息瓶颈自监督地把它从视频里挤出来。连续 latent 空间让动作可平均、可插值、可聚类，适配新环境变成低维查表而非重新学习。这是一个可移植的预训练范式，套到 iVideoGPT 上同样有效。</p><p><strong>1 句话版。</strong> 世界模型不该在适配时才第一次见到动作。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>智能体的动作构成了帧间变化的主导成分</strong>，因此信息瓶颈挤出来的必然是动作。</p><p>这在 Gym Retro 的 2D 游戏、Procgen、桌面机械臂这些场景里大体成立——背景静止，唯一在动的就是被控对象。但它在很多真实场景里直接失效：车流中的自车运动与其他车辆运动混在一起；Ego4D 里镜头晃动与场景中他人的活动同时存在；风吹树叶、光照变化、相机自动曝光都会产生与动作无关的强烈帧间变化。一旦这些干扰的信息量超过动作，32 维瓶颈会优先编码它们，latent action 就不再是动作。</p><p>论文自己给了两处线索。其一，UMAP 图里承认「噪声存在，因为某些状态下动作无法执行（比如前方有障碍时无法前进）」——这实际上是同一个问题的温和版本。其二，作者在相关工作里引用了 Nikulin et al. 2025 的《Latent Action Learning Requires Supervision in the Presence of Distractors》，那篇论文的结论恰恰与本文的核心假设相冲突，但正文没有对此做实验回应。数据混合上 Gym Retro 占 49%、Procgen 占 2%，即超过一半的训练信号来自干扰极少的 2D 游戏——这个比例本身就说明了方法对「干净」数据的偏好。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要 20 亿帧和 16 张 A100：</p><ol><li>只训 latent action autoencoder（可缩到 50M 参数），数据用 Procgen 的 4 个环境各 50 万帧，训 40K 步（与论文的数据多样性消融同量级）。</li><li>构造一个<strong>干扰对照</strong>：在同一批 Procgen 视频上叠加与动作无关的全局扰动（随机亮度抖动 + 缓慢的全局平移，模拟相机晃动），训第二个编码器。</li><li>测量：对两个编码器，各采 1000 条已知动作标签的样本，计算 latent action 的<strong>动作可分性</strong>——用一个线性分类器从 latent action 预测真实动作标签的准确率，以及跨环境的动作聚类重合度（论文用 UMAP 定性展示，这里改成定量的 silhouette 或 ARI）。</li><li>判据：如果加入温和扰动后线性可分准确率大幅下降（比如从 80% 掉到 50% 以下），就说明瓶颈确实会被非动作变化占据，§9 的假设脆弱；如果基本持平，则说明动作主导性比预期稳健，可以进一步加大扰动强度找到临界点。这个实验完全绕开了世界模型的训练，一周内可完成。</li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释。</strong> Procgen 规划实验里，AdaWorld 大幅超过 Q-learning 与动作无关基线，论文归因于「latent action 预训练带来的可适配控制接口」。但存在另一种解释：AdaWorld 的预训练数据里包含 Procgen 的 9000 个 start level（只留了 1000 个做评估），而动作无关基线虽然见过同样的像素，却因为条件恒为零而无法利用其中的动作结构——两者的差距可能主要来自<strong>对该环境视觉分布的熟悉程度与动作结构的可用性叠加</strong>，而非可迁移的控制接口本身。要检验，需要在一个训练数据里完全没有出现过的、且视觉风格与 Gym Retro/Procgen 都很远的环境上重复规划实验（Habitat 与 nuScenes 只测了仿真质量，没有测规划）。</p><p><strong>可预测失败的场景。</strong> 论文在 limitations 里承认，当 rollout 超出初始场景时模型难以创造新内容，且无法做极长时间的 rollout。把这两点与 MPC 结合，可以构造一个必然失败的设置：在 Procgen 的 Maze 上把搜索上限从 20 步提到 100 步，并选择目标点位于初始视野之外的场景。可以预期成功率会崩塌到接近随机——因为 MPC 的奖励是「预测观测与目标图像的余弦相似度」，而模型在长 rollout 中既不能生成初始视野外的新内容，误差又持续累积，奖励信号将变成噪声。论文选取场景时明确做了「可在可接受步数内到达」的穷举筛选（最终 120 个场景），这一筛选本身就回避了该失败模式。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限。</strong> latent action 目前是从<strong>两帧</strong>之间抽出来的，因此它天然是一个「单步、瞬时」的量。这带来两个后果：一是它无法表达有时间跨度的意图（「绕过这个障碍」不是任何单帧转移），二是 MPC 必须在这个原子动作空间里做搜索，长时规划的分支因子高得离谱，直接限制了 §11 里那个失败模式。作者用 K-means 做「动作创造」时其实已经触到了这个边界——聚类只能得到更多的原子动作，得不到更长的动作。</p><p><strong>新的 framing。</strong> 把 latent action 从「帧间转移的编码」升级为<strong>带时间尺度的分层表示</strong>：用同一个信息瓶颈原则，但让编码器在多个时间跨度上抽取（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9028em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9028em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">4</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9028em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">16</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span>），得到一族嵌套的 latent action，其中长跨度的编码天然对应「技能」而非「动作」。可借鉴的相邻领域工具是分层强化学习里的 options 框架与 temporal abstraction，以及语音/视频里的多尺度 VQ。关键的连接点在于：AdaWorld 已经证明连续 latent action 可以平均、可以插值，那么「长跨度 latent action ≈ 短跨度 latent action 序列的某种压缩」这一关系是可以被显式约束的（例如要求长跨度编码能重建出对应的短跨度编码序列）。</p><p><strong>第一个实验。</strong> 在现有 AdaWorld 的 latent action autoencoder 上加一个跨度为 8 帧的编码分支，共享 encoder 主干、独立瓶颈，训练目标是「仅凭 8 帧跨度的 latent skill 与首帧，重建第 8 帧」外加一个一致性项。之后在 Procgen Maze 上做两层 MPC：外层在 skill 空间搜索 5 步（等效 40 帧），内层用现有 latent action 细化。评估把搜索上限提到 100 步、目标点在初始视野外的场景成功率。如果分层版本相对扁平 MPC 有明显提升，就说明 latent action 的时间抽象是一个独立于「预训练是否含动作信息」的新维度；如果没有提升，则说明瓶颈在世界模型的长时 rollout 质量而非搜索结构，这会把后续研究的重心正确地推向 rollout 稳定性。</p>',57)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
